<script setup lang="ts">
import {computed,ref,onMounted,onBeforeUnmount} from 'vue';
import {usePlatform} from '../stores/platform';import {dataTypes} from '../domain';import ChartPanel from '../components/ChartPanel.vue';
import RemoteDashboard from '../components/RemoteDashboard.vue';
import {apiMode} from '../api/client';
const p=usePlatform(),rankType=ref('电围'),dedupType=ref('电围'),dedupClass=ref('日采集卡码量'),updated=ref(new Date().toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai'})),today=ref(12480),tip=ref('');let poll:ReturnType<typeof setInterval>|undefined,hover:ReturnType<typeof setTimeout>|undefined;
onMounted(()=>poll=setInterval(()=>{today.value++;updated.value=new Date().toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai'});},10000));onBeforeUnmount(()=>{clearInterval(poll);clearTimeout(hover);});
const power=computed(()=>['低功率','中功率','高功率'].map((name,i)=>{const ds=p.db.devices.filter(d=>(Number(d.params.power)<15?0:Number(d.params.power)<25?1:2)===i);return {name,total:ds.length,rate:ds.length?Math.round(ds.filter(d=>d.status==='在线').length/ds.length*100):0};}));
const rank=computed(()=>p.db.sites.map(s=>({name:s.name,count:p.db.captures.filter(c=>c.site===s.name&&c.type===rankType.value).length})).sort((a,b)=>b.count-a.count).slice(0,5));
function regionLeave(){clearTimeout(hover);tip.value='';}
function regionHover(region:string){clearTimeout(hover);hover=setTimeout(()=>{tip.value=region+' · '+dataTypes.map(t=>t+' '+p.db.devices.filter(d=>d.region===region&&d.type===t).length+' 台').join(' / ');},1000);}
</script>
<template><RemoteDashboard v-if="apiMode==='http'"/><div v-else class="dashboard-layout"><div class="stack"><section class="card"><h3>设备在线数量</h3><div v-for="row in power" :key="row.name" class="stat">{{row.name}}<b>{{row.total}} 台 · 在线率 {{row.rate}}%</b></div></section><ChartPanel title="近 7 天采集数据" :labels="dataTypes.slice(0,3)"/><section class="card"><div class="section-head"><h3>采集场所前五排行</h3><el-select v-model="rankType" aria-label="排行设备类型"><el-option v-for="t in dataTypes.slice(0,3)" :key="t" :value="t"/></el-select></div><ol class="ranking"><li v-for="(r,i) in rank" :key="r.name"><span>{{i+1}}. {{r.name}}</span><b>{{r.count}} 条</b></li></ol></section></div><div class="stack"><section class="card"><h3>当日采集 / 累计采集</h3><div class="totals"><div><p>当日采集（尚未全部入库）</p><strong>{{today.toLocaleString()}}</strong></div><div><p>累计采集</p><strong>12,800,000</strong></div></div><p class="muted">更新时间 {{updated}} · 每 10 秒演示更新</p></section><div class="two-column"><div class="stack"><section class="card"><h3>设备累计采集（已入库）</h3><div v-for="(t,i) in dataTypes.slice(0,3)" :key="t" class="stat">{{t}}<b>{{((i+1)*123000).toLocaleString()}} 条</b></div></section><section class="card"><h3>设备布控告警次数</h3><div v-for="(d,i) in p.db.devices.slice(0,4)" :key="d.id" class="stat">{{d.name}}<b>{{i+1}} 次</b></div></section></div><section class="card"><h3>设备分布</h3><div class="overview-map"><button v-for="(site,i) in p.db.sites" :key="site.id" class="region" :style="{left:(6+i%3*30)+'%',top:(12+Math.floor(i/3)*48)+'%'}" @mouseenter="regionHover(site.region)" @mouseleave="regionLeave" @focus="regionHover(site.region)" @blur="tip=''" @click="p.navigate('地图研判',{site:site.name,region:site.region})">{{site.region}}</button><div v-if="tip" class="map-tip" role="status">{{tip}}</div></div></section></div><section class="card"><div class="section-head"><h3>一周去重后采集数据</h3><el-select v-model="dedupType" aria-label="去重设备类型"><el-option v-for="t in dataTypes.slice(0,3)" :key="t" :value="t"/></el-select><el-select v-model="dedupClass" aria-label="去重数据分类"><el-option v-for="t in ['日采集卡码量','省外日采集卡码量','境外日采集卡码量']" :key="t" :value="t"/></el-select></div><ChartPanel :title="dedupClass" :labels="[dedupClass]" :scale="(dataTypes.indexOf(dedupType as typeof dataTypes[number])+1)*(['日采集卡码量','省外日采集卡码量','境外日采集卡码量'].indexOf(dedupClass)+1)"/></section><section class="card"><h3>数据归属地前十位排行</h3><div class="origin-rank"><span v-for="i in 10" :key="i">{{i}}. 示例地区{{i}} <b>{{1070-i*70}}</b></span></div></section></div><div class="stack"><section class="card"><h3>应用入口</h3><div class="app-entries"><el-button v-for="([label,page]) in [['数据检索','围栏检索'],['数据研判','伴随任务'],['综合分析','地图研判'],['布控预警','综合布控']]" :key="label" @click="p.navigate(page||'系统首页')">{{label}}</el-button></div></section><ChartPanel title="电围分类统计" :labels="['2G','4G','5G']" :count="30" exportable/><ChartPanel title="一周操作统计" :labels="['数据查询','数据分析','运维操作']" unit="次"/></div></div></template>

